// deterministic hash (FNV-1a 32-bit), no randomness
function h(s){let x=2166136261>>>0;for(let i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,16777619)>>>0;}return x>>>0;}
const KEYS=100000;
// --- modulo scheme: hash % N, N 4 -> 5 ---
let moduloMoved=0;
for(let i=0;i<KEYS;i++){const hv=h('key:'+i);if((hv%4)!==(hv%5))moduloMoved++;}
// --- virtual buckets: 1024 logical buckets bucket=hash%1024 ---
// bucket->node by bucket%N. 4 nodes -> 5 nodes.
let bucketKeysMoved=0;
for(let i=0;i<KEYS;i++){const b=h('key:'+i)%1024;if((b%4)!==(b%5))bucketKeysMoved++;}
// count distinct buckets that change owner
let bucketsMoved=0;for(let b=0;b<1024;b++){if((b%4)!==(b%5))bucketsMoved++;}
const pct=n=>((n/KEYS)*100).toFixed(1);
console.log('modulo keys moved: '+moduloMoved+' / '+KEYS+' ('+pct(moduloMoved)+'%)');
console.log('vbucket keys moved: '+bucketKeysMoved+' / '+KEYS+' ('+pct(bucketKeysMoved)+'%)');
console.log('buckets reassigned: '+bucketsMoved+' / 1024');
